def connect():
    conn = sqlite3.connect(DB_FILE, timeout=ZAMOK_OZHIDANIE, factory=Soedinenie)
    conn.row_factory = sqlite3.Row
    # Setup pragmas must not hold the transaction queue for a long-lived reader.
    try:
        sqlite3.Connection.execute(conn, "PRAGMA journal_mode=DELETE")
    except Exception:
        pass
    sqlite3.Connection.execute(
        conn, "PRAGMA busy_timeout=%d" % (ZAMOK_OZHIDANIE * 1000)
    )
    sqlite3.Connection.execute(conn, "PRAGMA foreign_keys=ON")
    return conn

async def error_handler(update, context):
    """Раньше ошибка внутреннего бота уходила только в лог, который
    никто не читает — теперь о ней узнаёт владелец."""
    logging.error("Ошибка в team_bot:", exc_info=context.error)
    tb = "".join(traceback.format_exception(
        None, context.error, context.error.__traceback__
    ))
    for uid in db.staff_ids_by_role(db.ROLE_OWNER):
        try:
            await context.bot.send_message(
                uid,
                f"⚠️ <b>Сбой во внутреннем боте</b>\n\n<code>{tb[-1000:]}</code>",
                parse_mode="HTML",
            )
        except Exception:
            pass
